insert into public.concepts (id, title, description, schema_version, content, visibility, origin)
values
  ('6a1f2c3e-0b4d-4e5f-8a6b-1c2d3e4f5a01', 'Raft leader election (simplified)', 'How five Raft servers pick a single leader with randomized timeouts and majority votes. Covers elections only: log replication and commit safety are out of scope.', 1, $seed${"schemaVersion":1,"id":"6a1f2c3e-0b4d-4e5f-8a6b-1c2d3e4f5a01","title":"Raft leader election (simplified)","description":"How five Raft servers pick a single leader with randomized timeouts and majority votes. Covers elections only: log replication and commit safety are out of scope.","steps":[{"id":"followers","text":"Five servers start as followers. Each waits to hear from a leader before its own timer runs out.","notes":"This story covers only how Raft picks a leader. Every server has an election timer set to a random duration (for example 150–300 ms); hearing from a leader resets it. The term is a logical clock that increases with each election.","nodes":[{"id":"s1","label":"S1 follower (term 1)","x":500,"y":95,"shape":"circle","color":"neutral","status":"active"},{"id":"s2","label":"S2 follower (term 1)","x":700,"y":235,"shape":"circle","color":"neutral","status":"active"},{"id":"s3","label":"S3 follower (term 1)","x":625,"y":455,"shape":"circle","color":"neutral","status":"active"},{"id":"s4","label":"S4 follower (term 1)","x":375,"y":455,"shape":"circle","color":"neutral","status":"active"},{"id":"s5","label":"S5 follower (term 1)","x":300,"y":235,"shape":"circle","color":"neutral","status":"active"}],"edges":[]},{"id":"crash","text":"S5 crashes. Raft can still elect a leader as long as a majority, three of five, are reachable.","notes":"A majority of five servers is three. Any two majorities share at least one server, which is what later stops two leaders from winning the same term.","nodes":[{"id":"s1","label":"S1 follower (term 1)","x":500,"y":95,"shape":"circle","color":"neutral","status":"active"},{"id":"s2","label":"S2 follower (term 1)","x":700,"y":235,"shape":"circle","color":"neutral","status":"active"},{"id":"s3","label":"S3 follower (term 1)","x":625,"y":455,"shape":"circle","color":"neutral","status":"active"},{"id":"s4","label":"S4 follower (term 1)","x":375,"y":455,"shape":"circle","color":"neutral","status":"active"},{"id":"s5","label":"S5 offline","x":300,"y":235,"shape":"circle","color":"danger","status":"inactive"}],"edges":[]},{"id":"timeout","text":"S3's timer expires first. It becomes a candidate, increases the term to 2, and votes for itself.","notes":"Randomized timeouts make it likely that one server times out well before the others, which lowers the chance that several candidates split the vote.","nodes":[{"id":"s1","label":"S1 follower (term 1)","x":500,"y":95,"shape":"circle","color":"neutral","status":"active"},{"id":"s2","label":"S2 follower (term 1)","x":700,"y":235,"shape":"circle","color":"neutral","status":"active"},{"id":"s3","label":"S3 candidate (term 2)","x":625,"y":455,"shape":"circle","color":"warning","status":"active"},{"id":"s4","label":"S4 follower (term 1)","x":375,"y":455,"shape":"circle","color":"neutral","status":"active"},{"id":"s5","label":"S5 offline","x":300,"y":235,"shape":"circle","color":"danger","status":"inactive"}],"edges":[]},{"id":"request-votes","text":"S3 sends RequestVote messages for term 2 to every other server, including the offline S5.","notes":"The message to S5 is simply lost. S3 does not need every server, only a majority.","nodes":[{"id":"s1","label":"S1 follower (term 1)","x":500,"y":95,"shape":"circle","color":"neutral","status":"active"},{"id":"s2","label":"S2 follower (term 1)","x":700,"y":235,"shape":"circle","color":"neutral","status":"active"},{"id":"s3","label":"S3 candidate (term 2)","x":625,"y":455,"shape":"circle","color":"warning","status":"active"},{"id":"s4","label":"S4 follower (term 1)","x":375,"y":455,"shape":"circle","color":"neutral","status":"active"},{"id":"s5","label":"S5 offline","x":300,"y":235,"shape":"circle","color":"danger","status":"inactive"}],"edges":[{"id":"rv1","from":"s3","to":"s1","label":"RequestVote (term 2)","animated":true},{"id":"rv2","from":"s3","to":"s2","label":"RequestVote (term 2)","animated":true},{"id":"rv4","from":"s3","to":"s4","label":"RequestVote (term 2)","animated":true},{"id":"rv5","from":"s3","to":"s5","label":"RequestVote (lost)","animated":true}]},{"id":"votes","text":"S1 and S2 grant their votes. Once they arrive, S3 will hold three of five: a majority.","notes":"Each server votes for at most one candidate per term, first come first served. Full Raft also refuses votes to candidates whose log is behind; this story leaves logs out. S4's reply is still in flight, and S3 no longer needs it.","nodes":[{"id":"s1","label":"S1 voted S3 (term 2)","x":500,"y":95,"shape":"circle","color":"success","status":"active"},{"id":"s2","label":"S2 voted S3 (term 2)","x":700,"y":235,"shape":"circle","color":"success","status":"active"},{"id":"s3","label":"S3 candidate (term 2)","x":625,"y":455,"shape":"circle","color":"warning","status":"active"},{"id":"s4","label":"S4 follower (term 2)","x":375,"y":455,"shape":"circle","color":"neutral","status":"active"},{"id":"s5","label":"S5 offline","x":300,"y":235,"shape":"circle","color":"danger","status":"inactive"}],"edges":[{"id":"vote1","from":"s1","to":"s3","label":"Vote granted","animated":true},{"id":"vote2","from":"s2","to":"s3","label":"Vote granted","animated":true}]},{"id":"leader","text":"With three of five votes, a majority, S3 becomes leader for term 2 and sends heartbeats.","notes":"Heartbeats are AppendEntries messages that carry no log entries. In full Raft the same message type also replicates the log, which this story does not cover.","nodes":[{"id":"s1","label":"S1 follower (term 2)","x":500,"y":95,"shape":"circle","color":"neutral","status":"active"},{"id":"s2","label":"S2 follower (term 2)","x":700,"y":235,"shape":"circle","color":"neutral","status":"active"},{"id":"s3","label":"S3 leader (term 2)","x":625,"y":455,"shape":"circle","color":"primary","status":"active"},{"id":"s4","label":"S4 follower (term 2)","x":375,"y":455,"shape":"circle","color":"neutral","status":"active"},{"id":"s5","label":"S5 offline","x":300,"y":235,"shape":"circle","color":"danger","status":"inactive"}],"edges":[{"id":"hb1","from":"s3","to":"s1","label":"Heartbeat","animated":true},{"id":"hb2","from":"s3","to":"s2","label":"Heartbeat","animated":true},{"id":"hb4","from":"s3","to":"s4","label":"Heartbeat","animated":true}]},{"id":"heartbeats","text":"Each heartbeat resets a follower's election timer, so no follower starts a competing election.","notes":"The leader keeps sending heartbeats more often than the shortest election timeout. If heartbeats stop because the leader fails, a follower times out and a new election begins with a higher term.","nodes":[{"id":"s1","label":"S1 timer reset","x":500,"y":95,"shape":"circle","color":"secondary","status":"active"},{"id":"s2","label":"S2 timer reset","x":700,"y":235,"shape":"circle","color":"secondary","status":"active"},{"id":"s3","label":"S3 leader (term 2)","x":625,"y":455,"shape":"circle","color":"primary","status":"active"},{"id":"s4","label":"S4 timer reset","x":375,"y":455,"shape":"circle","color":"secondary","status":"active"},{"id":"s5","label":"S5 offline","x":300,"y":235,"shape":"circle","color":"danger","status":"inactive"}],"edges":[{"id":"hb1","from":"s3","to":"s1","label":"Heartbeat","animated":true},{"id":"hb2","from":"s3","to":"s2","label":"Heartbeat","animated":true},{"id":"hb4","from":"s3","to":"s4","label":"Heartbeat","animated":true}]},{"id":"recover","text":"S5 restarts, still on term 1. The leader's heartbeat for term 2 is on its way.","notes":"When the heartbeat arrives, S5 sees a higher term than its own, adopts term 2, and becomes a follower. That is how a stale server rejoins without disrupting the current leader.","nodes":[{"id":"s1","label":"S1 follower (term 2)","x":500,"y":95,"shape":"circle","color":"neutral","status":"active"},{"id":"s2","label":"S2 follower (term 2)","x":700,"y":235,"shape":"circle","color":"neutral","status":"active"},{"id":"s3","label":"S3 leader (term 2)","x":625,"y":455,"shape":"circle","color":"primary","status":"active"},{"id":"s4","label":"S4 follower (term 2)","x":375,"y":455,"shape":"circle","color":"neutral","status":"active"},{"id":"s5","label":"S5 restarted (term 1)","x":300,"y":235,"shape":"circle","color":"neutral","status":"active"}],"edges":[{"id":"hb1","from":"s3","to":"s1","label":"Heartbeat","animated":false},{"id":"hb2","from":"s3","to":"s2","label":"Heartbeat","animated":false},{"id":"hb4","from":"s3","to":"s4","label":"Heartbeat","animated":false},{"id":"hb5","from":"s3","to":"s5","label":"Heartbeat (term 2)","animated":true}]},{"id":"takeaway","text":"Takeaway: one vote per server per term, plus majority wins, means at most one leader per term.","notes":"S5 has now received the heartbeat and follows S3 in term 2. This is Raft's Election Safety property. It does not by itself guarantee that committed log entries survive leader changes; full Raft adds log replication rules and a voting restriction for that. Elections can also fail when votes split, in which case servers time out again with new random timeouts.","nodes":[{"id":"s1","label":"S1 follower (term 2)","x":500,"y":95,"shape":"circle","color":"neutral","status":"active"},{"id":"s2","label":"S2 follower (term 2)","x":700,"y":235,"shape":"circle","color":"neutral","status":"active"},{"id":"s3","label":"S3 leader (term 2)","x":625,"y":455,"shape":"circle","color":"success","status":"active"},{"id":"s4","label":"S4 follower (term 2)","x":375,"y":455,"shape":"circle","color":"neutral","status":"active"},{"id":"s5","label":"S5 follower (term 2)","x":300,"y":235,"shape":"circle","color":"neutral","status":"active"}],"edges":[{"id":"hb1","from":"s3","to":"s1","label":"Heartbeat","animated":false},{"id":"hb2","from":"s3","to":"s2","label":"Heartbeat","animated":false},{"id":"hb4","from":"s3","to":"s4","label":"Heartbeat","animated":false},{"id":"hb5","from":"s3","to":"s5","label":"Heartbeat","animated":false}]}]}$seed$::jsonb, 'public', 'curated'),
  ('6a1f2c3e-0b4d-4e5f-8a6b-1c2d3e4f5a02', 'How DNS finds an address', 'Follow one lookup for example.com from your laptop through a recursive resolver, the root, the .com servers, and the domain''s own name server, then see why the second lookup is instant.', 1, $seed${"schemaVersion":1,"id":"6a1f2c3e-0b4d-4e5f-8a6b-1c2d3e4f5a02","title":"How DNS finds an address","description":"Follow one lookup for example.com from your laptop through a recursive resolver, the root, the .com servers, and the domain's own name server, then see why the second lookup is instant.","steps":[{"id":"start","text":"Your laptop wants to open example.com, but it needs the site's IP address first.","notes":"Computers connect using IP addresses. DNS, the Domain Name System, translates names like example.com into addresses. The operating system usually forwards the question to a recursive resolver run by an ISP, a company, or a public DNS service.","nodes":[{"id":"laptop","label":"Your laptop","x":140,"y":300,"shape":"square","color":"primary","status":"active"},{"id":"resolver","label":"Recursive resolver","x":400,"y":300,"shape":"circle","color":"neutral","status":"active"}],"edges":[]},{"id":"ask-resolver","text":"The laptop asks its recursive resolver: what is the IPv4 address (A record) for example.com?","nodes":[{"id":"laptop","label":"Your laptop","x":140,"y":300,"shape":"square","color":"primary","status":"active"},{"id":"resolver","label":"Recursive resolver","x":400,"y":300,"shape":"circle","color":"neutral","status":"active"}],"edges":[{"id":"q1","from":"laptop","to":"resolver","label":"A example.com?","animated":true}]},{"id":"cache-miss","text":"The resolver finds no cached answer, so it asks a root name server where to look.","notes":"Resolvers ship with a list of root server addresses, so they always know where to start.","nodes":[{"id":"laptop","label":"Your laptop","x":140,"y":300,"shape":"square","color":"neutral","status":"active"},{"id":"resolver","label":"Resolver: cache miss","x":400,"y":300,"shape":"circle","color":"warning","status":"active"},{"id":"root","label":"Root name server","x":720,"y":95,"shape":"circle","color":"neutral","status":"active"}],"edges":[{"id":"q1","from":"laptop","to":"resolver","label":"A example.com?","animated":false},{"id":"q2","from":"resolver","to":"root","label":"A example.com?","animated":true}]},{"id":"root-referral","text":"The root server doesn't know the address, but refers the resolver to the .com servers.","notes":"Root servers only know which servers are responsible for each top-level domain, such as .com, .org, or .uk. Referrals are answers too: they say who to ask next.","nodes":[{"id":"laptop","label":"Your laptop","x":140,"y":300,"shape":"square","color":"neutral","status":"active"},{"id":"resolver","label":"Resolver: cache miss","x":400,"y":300,"shape":"circle","color":"warning","status":"active"},{"id":"root","label":"Root name server","x":720,"y":95,"shape":"circle","color":"secondary","status":"active"},{"id":"tld","label":".com TLD server","x":840,"y":300,"shape":"circle","color":"neutral","status":"active"}],"edges":[{"id":"q1","from":"laptop","to":"resolver","label":"A example.com?","animated":false},{"id":"r1","from":"root","to":"resolver","label":"Referral: .com servers","animated":true}]},{"id":"ask-tld","text":"The resolver repeats the same question to a .com TLD server.","nodes":[{"id":"laptop","label":"Your laptop","x":140,"y":300,"shape":"square","color":"neutral","status":"active"},{"id":"resolver","label":"Resolver: cache miss","x":400,"y":300,"shape":"circle","color":"warning","status":"active"},{"id":"root","label":"Root name server","x":720,"y":95,"shape":"circle","color":"neutral","status":"inactive"},{"id":"tld","label":".com TLD server","x":840,"y":300,"shape":"circle","color":"neutral","status":"active"}],"edges":[{"id":"q1","from":"laptop","to":"resolver","label":"A example.com?","animated":false},{"id":"q3","from":"resolver","to":"tld","label":"A example.com?","animated":true}]},{"id":"tld-referral","text":"The .com server refers it to example.com's own authoritative name servers.","nodes":[{"id":"laptop","label":"Your laptop","x":140,"y":300,"shape":"square","color":"neutral","status":"active"},{"id":"resolver","label":"Resolver: cache miss","x":400,"y":300,"shape":"circle","color":"warning","status":"active"},{"id":"root","label":"Root name server","x":720,"y":95,"shape":"circle","color":"neutral","status":"inactive"},{"id":"tld","label":".com TLD server","x":840,"y":300,"shape":"circle","color":"secondary","status":"active"},{"id":"auth","label":"example.com name server","x":720,"y":490,"shape":"circle","color":"neutral","status":"active"}],"edges":[{"id":"q1","from":"laptop","to":"resolver","label":"A example.com?","animated":false},{"id":"r2","from":"tld","to":"resolver","label":"Referral: example.com NS","animated":true}]},{"id":"ask-auth","text":"The resolver asks the authoritative server, which holds the actual records for example.com.","nodes":[{"id":"laptop","label":"Your laptop","x":140,"y":300,"shape":"square","color":"neutral","status":"active"},{"id":"resolver","label":"Resolver: cache miss","x":400,"y":300,"shape":"circle","color":"warning","status":"active"},{"id":"root","label":"Root name server","x":720,"y":95,"shape":"circle","color":"neutral","status":"inactive"},{"id":"tld","label":".com TLD server","x":840,"y":300,"shape":"circle","color":"neutral","status":"inactive"},{"id":"auth","label":"example.com name server","x":720,"y":490,"shape":"circle","color":"neutral","status":"active"}],"edges":[{"id":"q1","from":"laptop","to":"resolver","label":"A example.com?","animated":false},{"id":"q4","from":"resolver","to":"auth","label":"A example.com?","animated":true}]},{"id":"answer","text":"The authoritative server answers with the address and a time-to-live (TTL) of 300 seconds.","notes":"203.0.113.10 is a reserved documentation address used here as an example. The TTL tells resolvers how long they may reuse the answer before asking again.","nodes":[{"id":"laptop","label":"Your laptop","x":140,"y":300,"shape":"square","color":"neutral","status":"active"},{"id":"resolver","label":"Resolver: cache miss","x":400,"y":300,"shape":"circle","color":"warning","status":"active"},{"id":"root","label":"Root name server","x":720,"y":95,"shape":"circle","color":"neutral","status":"inactive"},{"id":"tld","label":".com TLD server","x":840,"y":300,"shape":"circle","color":"neutral","status":"inactive"},{"id":"auth","label":"example.com name server","x":720,"y":490,"shape":"circle","color":"success","status":"active"}],"edges":[{"id":"q1","from":"laptop","to":"resolver","label":"A example.com?","animated":false},{"id":"a1","from":"auth","to":"resolver","label":"A 203.0.113.10, TTL 300","animated":true}]},{"id":"cache-and-reply","text":"The resolver caches the answer for 300 seconds and returns the address to your laptop.","nodes":[{"id":"laptop","label":"Your laptop","x":140,"y":300,"shape":"square","color":"primary","status":"active"},{"id":"resolver","label":"Resolver: cached 300 s","x":400,"y":300,"shape":"circle","color":"success","status":"active"},{"id":"root","label":"Root name server","x":720,"y":95,"shape":"circle","color":"neutral","status":"inactive"},{"id":"tld","label":".com TLD server","x":840,"y":300,"shape":"circle","color":"neutral","status":"inactive"},{"id":"auth","label":"example.com name server","x":720,"y":490,"shape":"circle","color":"neutral","status":"inactive"}],"edges":[{"id":"a2","from":"resolver","to":"laptop","label":"203.0.113.10","animated":true}]},{"id":"connect","text":"Now the laptop can open a connection to the web server at 203.0.113.10.","notes":"DNS only supplies the address. Opening the HTTPS connection is a separate protocol step.","nodes":[{"id":"laptop","label":"Your laptop","x":140,"y":300,"shape":"square","color":"primary","status":"active"},{"id":"resolver","label":"Resolver: cached 300 s","x":400,"y":300,"shape":"circle","color":"success","status":"active"},{"id":"root","label":"Root name server","x":720,"y":95,"shape":"circle","color":"neutral","status":"inactive"},{"id":"tld","label":".com TLD server","x":840,"y":300,"shape":"circle","color":"neutral","status":"inactive"},{"id":"auth","label":"example.com name server","x":720,"y":490,"shape":"circle","color":"neutral","status":"inactive"},{"id":"web","label":"example.com web server","x":140,"y":490,"shape":"square","color":"success","status":"active"}],"edges":[{"id":"c1","from":"laptop","to":"web","label":"HTTPS to 203.0.113.10","animated":true}]},{"id":"cache-hit","text":"Takeaway: another lookup within 300 seconds is answered from the resolver's cache, skipping three servers.","notes":"Caching happens at several levels: browser, operating system, and resolver. Cached answers can be stale until the TTL expires, which is why DNS changes take time to be seen everywhere. Resolvers also cache referrals, so even a different .com name can skip the root.","nodes":[{"id":"laptop","label":"Your laptop","x":140,"y":300,"shape":"square","color":"primary","status":"active"},{"id":"resolver","label":"Resolver: cache hit","x":400,"y":300,"shape":"circle","color":"success","status":"active"},{"id":"root","label":"Root name server","x":720,"y":95,"shape":"circle","color":"neutral","status":"inactive"},{"id":"tld","label":".com TLD server","x":840,"y":300,"shape":"circle","color":"neutral","status":"inactive"},{"id":"auth","label":"example.com name server","x":720,"y":490,"shape":"circle","color":"neutral","status":"inactive"},{"id":"web","label":"example.com web server","x":140,"y":490,"shape":"square","color":"neutral","status":"inactive"}],"edges":[{"id":"q5","from":"laptop","to":"resolver","label":"A example.com?","animated":false},{"id":"a3","from":"resolver","to":"laptop","label":"Cached: 203.0.113.10","animated":true}]}]}$seed$::jsonb, 'public', 'curated'),
  ('6a1f2c3e-0b4d-4e5f-8a6b-1c2d3e4f5a03', 'Binary search', 'Find 34 in a sorted list of seven numbers by checking the middle and discarding half of the remaining range each time.', 1, $seed${"schemaVersion":1,"id":"6a1f2c3e-0b4d-4e5f-8a6b-1c2d3e4f5a03","title":"Binary search","description":"Find 34 in a sorted list of seven numbers by checking the middle and discarding half of the remaining range each time.","steps":[{"id":"sorted-list","text":"Binary search finds a value in a sorted list by repeatedly halving the range where it could be.","notes":"The list must already be sorted in ascending order. Each square is one element; the number in brackets is its index.","nodes":[{"id":"cell-0","label":"[0] 3","x":140,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-1","label":"[1] 8","x":260,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-2","label":"[2] 15","x":380,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-3","label":"[3] 21","x":500,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-4","label":"[4] 34","x":620,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-5","label":"[5] 42","x":740,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-6","label":"[6] 57","x":860,"y":360,"shape":"square","color":"neutral","status":"active"}],"edges":[]},{"id":"target","text":"We are looking for 34. At first the whole list, index 0 to 6, could contain it.","notes":"'low' and 'high' mark the first and last index of the range that could still hold the target.","nodes":[{"id":"target","label":"Target: 34","x":500,"y":130,"shape":"circle","color":"secondary","status":"active"},{"id":"cell-0","label":"[0] 3 · low","x":140,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-1","label":"[1] 8","x":260,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-2","label":"[2] 15","x":380,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-3","label":"[3] 21","x":500,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-4","label":"[4] 34","x":620,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-5","label":"[5] 42","x":740,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-6","label":"[6] 57 · high","x":860,"y":360,"shape":"square","color":"neutral","status":"active"}],"edges":[]},{"id":"first-middle","text":"Check the middle of the range: index 3, which holds 21.","notes":"The middle index is (low + high) / 2, rounded down: (0 + 6) / 2 = 3.","nodes":[{"id":"target","label":"Target: 34","x":500,"y":130,"shape":"circle","color":"secondary","status":"active"},{"id":"cell-0","label":"[0] 3 · low","x":140,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-1","label":"[1] 8","x":260,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-2","label":"[2] 15","x":380,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-3","label":"[3] 21 · mid","x":500,"y":360,"shape":"square","color":"primary","status":"active"},{"id":"cell-4","label":"[4] 34","x":620,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-5","label":"[5] 42","x":740,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-6","label":"[6] 57 · high","x":860,"y":360,"shape":"square","color":"neutral","status":"active"}],"edges":[{"id":"cmp1","from":"target","to":"cell-3","label":"34 vs 21","animated":true}]},{"id":"discard-left","text":"34 is larger than 21, so 34 can only be to the right. Discard indices 0 to 3.","notes":"Because the list is sorted, every element at or left of index 3 is at most 21, so none of them can be 34. One comparison removed four of the seven candidates.","nodes":[{"id":"target","label":"Target: 34","x":500,"y":130,"shape":"circle","color":"secondary","status":"active"},{"id":"cell-0","label":"[0] 3","x":140,"y":360,"shape":"square","color":"neutral","status":"inactive"},{"id":"cell-1","label":"[1] 8","x":260,"y":360,"shape":"square","color":"neutral","status":"inactive"},{"id":"cell-2","label":"[2] 15","x":380,"y":360,"shape":"square","color":"neutral","status":"inactive"},{"id":"cell-3","label":"[3] 21","x":500,"y":360,"shape":"square","color":"neutral","status":"inactive"},{"id":"cell-4","label":"[4] 34 · low","x":620,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-5","label":"[5] 42","x":740,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-6","label":"[6] 57 · high","x":860,"y":360,"shape":"square","color":"neutral","status":"active"}],"edges":[]},{"id":"second-middle","text":"The new range is indices 4 to 6. Its middle, index 5, holds 42.","notes":"(4 + 6) / 2 = 5. The target moves over the element it is compared with.","nodes":[{"id":"target","label":"Target: 34","x":740,"y":130,"shape":"circle","color":"secondary","status":"active"},{"id":"cell-0","label":"[0] 3","x":140,"y":360,"shape":"square","color":"neutral","status":"inactive"},{"id":"cell-1","label":"[1] 8","x":260,"y":360,"shape":"square","color":"neutral","status":"inactive"},{"id":"cell-2","label":"[2] 15","x":380,"y":360,"shape":"square","color":"neutral","status":"inactive"},{"id":"cell-3","label":"[3] 21","x":500,"y":360,"shape":"square","color":"neutral","status":"inactive"},{"id":"cell-4","label":"[4] 34 · low","x":620,"y":360,"shape":"square","color":"neutral","status":"active"},{"id":"cell-5","label":"[5] 42 · mid","x":740,"y":360,"shape":"square","color":"primary","status":"active"},{"id":"cell-6","label":"[6] 57 · high","x":860,"y":360,"shape":"square","color":"neutral","status":"active"}],"edges":[{"id":"cmp2","from":"target","to":"cell-5","label":"34 vs 42","animated":true}]},{"id":"discard-right","text":"34 is smaller than 42, so discard index 5 and everything to its right.","nodes":[{"id":"target","label":"Target: 34","x":740,"y":13